// l4_reply_plan.js — plan which comments need replies
const fs = require('fs');
const planModule = fs.readFileSync('/home/node/.n8n/code/l4_reply_plan.js', 'utf8');
eval(planModule);

const input = {
  posts: $('Fetch posts with comments').all().map(item => item.json),
  comments: $input.all().map(item => item.json),
  l4_settings: $('Load L4 config').first().json.value || {},
  recent_replies: [],
  self_username: ''
};

const result = planReplies(input);
if (result.length === 0) {
  return [{ json: { _empty: true, message: 'No comments need replies' } }];
}
return result.map(r => ({ json: { ...input, ...r } }));

