// l4_qa_reply.js — QA gate for drafted replies
const fs = require('fs');
const qaModule = fs.readFileSync('/home/node/.n8n/code/l4_qa_reply.js', 'utf8');
eval(qaModule);

const base = $('Draft reply prompt').first().json;
const llmResponse = $input.first().json;
const replyText = llmResponse.choices?.[0]?.message?.content || '';

const input = {
  ...base,
  reply_text: replyText,
  settings: base.l4_settings || {}
};

const result = qaReply(input);
return [{ json: { ...input, ...result } }];

// Prepare Threads API comment fetch URLs
const posts = $input.all().map(item => item.json);
const token = $('Load L4 config').first().json.value?.threads_token || '';

if (!token) {
  return [{ json: { _error: 'threads_token not configured in l4_reply settings' } }];
}
if (!posts.length) {
  return [{ json: { _empty: true, message: 'No posts to fetch comments for' } }];
}

const THREADS_API_BASE = 'https://graph.threads.net/v1.0';
return posts
  .filter(p => p.threads_media_id)
  .map(post => ({
    json: {
      fetch_url: `${THREADS_API_BASE}/${post.threads_media_id}/replies`,
      fetch_query: {
        access_token: token,
        fields: 'id,text,username,timestamp'
      },
      post_id: post.id,
      post_uid: post.uid,
      threads_media_id: post.threads_media_id
    }
  }));

// Process Threads API comment response
const response = $json;
const postId = $json.post_id;
const postUid = $json.post_uid;

if (response._error || response._empty) {
  return [{ json: { ...response, post_id: postId, post_uid: postUid } }];
}

const data = response.data || [];
if (!data.length) {
  return [{ json: { _empty: true, message: 'No comments returned', post_id: postId, post_uid: postUid } }];
}

return data.map(comment => ({
  json: {
    post_id: postId,
    post_uid: postUid,
    comment_id: comment.id,
    text: comment.text || '',
    username: comment.username || 'unknown',
    created_at: comment.timestamp ? new Date(comment.timestamp).toISOString() : new Date().toISOString()
  }
}));
